package com.dudleylane.quickfix.fix42;

/** FIX 4.2 ExecutionReport (35=8). Generated by spec/GeneratorJava.rb. */
public class ExecutionReport extends Message {
    public static final String MSGTYPE = "8";

    public ExecutionReport() {
        getHeader().setField(35, MSGTYPE);
    }

    private ExecutionReport(long cPtr) {
        super(cPtr, false);
    }

    /**
     * message as a ExecutionReport, without copying it: the same engine object, and the view keeps message from being
     * collected. A callback's message is the engine's and lasts only for the callback, and message.delete() ends
     * the view; copy it (new Message(message)) to keep it.
     */
    public static ExecutionReport view(com.dudleylane.quickfix.Message message) {
        if (!MSGTYPE.equals(message.getHeader().getField(35))) {
            throw new IllegalArgumentException("not a ExecutionReport (35=" + MSGTYPE + "): 35=" + message.getHeader().getField(35));
        }
        ExecutionReport view = new ExecutionReport(getCPtr(message));
        view.swigOwner = message;
        return view;
    }

    /** A new NoContraBrokers group, as this one holds it. */
    public static com.dudleylane.quickfix.fix42.group.NoContraBrokers newNoContraBrokers() {
        return new com.dudleylane.quickfix.fix42.group.NoContraBrokers();
    }
}
